head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[ModelUtil > M > findInstanceNode]<br/>Instance 내부에서 XPath 에 해당하는 노드를 반환합니다. 여러 개의 노드가 존재하면 첫 번째 노드를 반환합니다.",
    "validation" : [
        "xpath(필수) 파라미터로 반환할 Instance 노드의 XPath 경로를 설정할 수 있어야 합니다.",
        "xpath 파라미터에 해당하는 XML Element 노드를 반환해야 합니다.",
        "여러 개의 노드가 존재하면 첫 번째 노드를 반환해야 합니다.",
        "xpath 파라미터에 해당하는 노드가 없으면 null 을 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 특정 xpath 노드를 serialize 하여 한 줄 문자열로 반환 (출력용)
scwin.dumpXPath = function (xpath) {
    var node = WebSquare.ModelUtil.findInstanceNode(xpath);
    if (!node) return "(node not found)";
    var s = WebSquare.xml.serialize(node);
    return s.replace(/\s+/g, " ").replace(/>\s+</g, "><");
};



scwin.btn_findInstanceNode_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : 가이드 예제 - 동일 xpath 여러 노드 중 첫번째 반환
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : bookstore/book (여러 노드 → 첫번째 반환) ──");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 노드 : " + scwin.dumpXPath("bookstore/book"));
    } else if (scenario === "2") {
        // 시나리오 2 : 단일 노드 xpath
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : bookstore/book[2]/title (단일 노드 반환) ──");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 노드 : " + scwin.dumpXPath("bookstore/book[2]/title"));
    } else if (scenario === "3") {
        // 시나리오 3 : 존재하지 않는 xpath → null 반환
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : 존재하지 않는 xpath (bookstore/notExist) ──");

        var node = WebSquare.ModelUtil.findInstanceNode("bookstore/notExist");
        wf_body_bottom.getObj("scwin").setReturnValue("반환값 : " + node);
    }
};
